// Get the 4D lifted coordinates of the cell's vertices
std::vector<RT::Point> vertices;
for (RT::Vertex_handle v : c->vertices())
    vertices.push_back(v->point());

// Calculate the hyperplane equation in 4D (Ax + By + Cz + Dt + Ew = 0)
double A = 0, B = 0, C = 0, D = 0, E = 0;
for (size_t i = 0; i < vertices.size(); ++i) {
    for (size_t j = i + 1; j < vertices.size(); ++j) {
        for (size_t k = j + 1; k < vertices.size(); ++k) {
            RT::Point p1 = vertices[i];
            RT::Point p2 = vertices[j];
            RT::Point p3 = vertices[k];

            // Cross product in 4D (using 3D coordinates and time)
            double x1 = p1[0], y1 = p1[1], z1 = p1[2], t1 = p1[3];
            double x2 = p2[0], y2 = p2[1], z2 = p2[2], t2 = p2[3];
            double x3 = p3[0], y3 = p3[1], z3 = p3[2], t3 = p3[3];

            // Compute normal vector (A,B,C,D,E) using 4D cross product
            double a = (y2 - y1) * (z3 - z1) - (z2 - z1) * (y3 - y1);
            double b = (z2 - z1) * (x3 - x1) - (x2 - x1) * (z3 - z1);
            double c = (x2 - x1) * (y3 - y1) - (y2 - y1) * (x3 - x1);
            double d = (y2 - y1) * (t3 - t1) - (t2 - t1) * (y3 - y1);
            double e = (z2 - z1) * (t3 - t1) - (t2 - t1) * (z3 - z1);

            // Accumulate normal vector (simplified for demonstration)
            A += a; B += b; C += c; D += d; E += e;
        }
    }
}

// Normalize the hyperplane normal (A,B,C,D,E)
double norm = std::sqrt(A*A + B*B + C*C + D*D + E*E);
if (norm > 1e-10) {
    A /= norm; B /= norm; C /= norm; D /= norm; E /= norm;
}

// Calculate velocity vector (projection of time direction onto hyperplane)
double velocity_magnitude = -D / E;  // Assuming E != 0 (time component)
Vector velocity(B, C, velocity_magnitude);  // Velocity is (B, C, v_t)

return velocity;
// END_CODE

